function pointerDown(e){if(e.button>1)return;const canvas=e.currentTarget;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);pointerState.set(e.pointerId,{x:e.clientX,y:e.clientY});let paint=tool!=='probe'&&!e.altKey;gesture={canvas,id:e.pointerId,startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false,paint,pan:e.shiftKey||e.button===1};if(paint){brush.active=true;brush.pos=pointerPos(e,canvas);brush.direction=[1,0];applyBrush(.1);if(paused&&renderer)renderer.upload(sim);}e.preventDefault();}
