$('world').addEventListener('wheel',e=>{e.preventDefault();if(camera.fly)camera.pos=vadd(camera.pos,vmul(camera.basis().forward,-Math.sign(e.deltaY)*.8));else camera.distance=clamp(camera.distance*Math.exp(e.deltaY*.001),5,65);interactions.zooms++;},{passive:false});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if($('modal').classList.contains('open')){if(e.key==='Escape')closeModal();return;}keys.add(e.key.toLowerCase());if(e.code==='Space'){e.preventDefault();setPaused(!paused);}if(e.key==='.'){e.preventDefault();$('stepBtn').click();}if(e.key.toLowerCase()==='r')$('resetBtn').click();if(e.key.toLowerCase()==='l')strike(true);if(e.key==='Escape'){setTool('probe');closeDrawers();}if(e.key==='?')openHelp();if(e.key==='ArrowLeft')camera.azimuth+=.07;if(e.key==='ArrowRight')camera.azimuth-=.07;if(e.key==='ArrowUp')camera.elevation=clamp(camera.elevation+.05,.02,1.4);if(e.key==='ArrowDown')camera.elevation=clamp(camera.elevation-.05,.02,1.4);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();brush.active=false;gesture=null;pointerState.clear();});
function updateFly(dt){if(!camera.fly)return;let b=camera.basis(),speed=dt*(keys.has('shift')?10:4),direction=[0,0,0];if(keys.has('w'))direction=vadd(direction,b.forward);if(keys.has('s'))direction=vsub(direction,b.forward);if(keys.has('a'))direction=vsub(direction,b.right);if(keys.has('d'))direction=vadd(direction,b.right);if(keys.has('q'))direction[1]-=1;if(keys.has('e'))direction[1]+=1;camera.pos=vadd(camera.pos,vmul(direction,speed));camera.pos[1]=clamp(camera.pos[1],.3,18);}
