function drawMinimap(){drawGrid($('minimap'),false,true);}function drawFieldView(){drawGrid($('fieldView'),view==='section',false);}
function updateProbeMarker(){if(view!=='3d')return;const s=clamp(Math.round(probe.z*(sim.n-1)),0,sim.n-1)*sim.n+clamp(Math.round(probe.x*(sim.n-1)),0,sim.n-1),pos=camera.project([probe.x*24-12,sim.h[s]+.15,probe.z*24-12],$('world'));const m=$('probeMarker');if(pos&&pos[0]>=0&&pos[0]<$('scene').clientWidth&&pos[1]>=0&&pos[1]<$('scene').clientHeight){m.style.display='block';m.style.left=pos[0]+'px';m.style.top=pos[1]+'px';}else m.style.display='none';}
function strike(manual=false){let max=-1,location=0;for(let i=0;i<sim.f.c.length;i++){let intensity=sim.f.c[i]*Math.max(.03,sim.f.w[i]);if(intensity>max){max=intensity;location=i;}}if(!manual&&(max<.1||sim.charge<.003))return;const S=sim.n*sim.n,k=Math.floor(location/S),s=location%S,x=s%sim.n,z=Math.floor(s/sim.n),wx=x/(sim.n-1)*24-12,wz=z/(sim.n-1)*24-12,top=clamp(k*10/(sim.l-1)+1,3,9),bottom=sim.h[s]+.08;let segments=[],previous=[wx,top,wz];for(let j=1;j<=20;j++){let t=j/20,current=[wx+(sim.rand()-.5)*.65,top+(bottom-top)*t,wz+(sim.rand()-.5)*.65];segments.push([previous,current]);if(j%4===0){let branch=current;for(let b=0;b<5;b++){let next=[branch[0]+(sim.rand()-.5)*.65,branch[1]-.18,branch[2]+(sim.rand()-.5)*.65];segments.push([branch,next]);branch=next;}}previous=current;}bolt={created:performance.now()/1000,segments,position:[wx,top,wz],manual};lastBolt=sim.time;lightningCount++;if(!manual)autoLightningCount++;if(audioEnabled)thunder(wx,wz);if(manual)toast('Lightning triggered at the strongest storm column.');}
$('lightningBtn').onclick=()=>strike(true);
async function toggleAudio(){try{if(!audio){const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)throw Error('Web Audio is unavailable.');audio=new AudioCtx();}await audio.resume();audioEnabled=!audioEnabled;$('audioBtn').setAttribute('aria-pressed',audioEnabled);$('audioBtn').innerHTML=icon('sound')+'<span>'+(audioEnabled?'Sound on':'Sound off')+'</span>';if(!audioEnabled){for(let t of audioTimers)clearTimeout(t);audioTimers=[];}toast(audioEnabled?'Synthesized, distance-delayed thunder enabled.':'Thunder muted.');}catch(e){toast('Audio unavailable: '+e.message);}}
$('audioBtn').onclick=toggleAudio;
function thunder(x,z){let dx=x-(probe.x*24-12),dz=z-(probe.z*24-12),distance=Math.hypot(dx,dz)*2000,delay=clamp(distance/343,.18,15);const timer=setTimeout(()=>{if(!audioEnabled||!audio)return;const duration=3,rate=audio.sampleRate,buffer=audio.createBuffer(1,rate*duration,rate),data=buffer.getChannelData(0);let smooth=0;for(let i=0;i<data.length;i++){let t=i/rate,sample=Math.random()*2-1;smooth=smooth*.96+sample*.04;data[i]=smooth*Math.exp(-t*1.2)*(1+Math.sin(t*15)*.3);}let source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=250;gain.gain.value=clamp(.7/(1+distance/8000),.06,.6);source.connect(filter);filter.connect(gain);gain.connect(audio.destination);source.start();},delay*1000);audioTimers.push(timer);}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function saveState(){const state=sim.serialize();state.application={paused,render:{...renderSettings},camera:{target:[...camera.target],azimuth:camera.azimuth,elevation:camera.elevation,distance:camera.distance,fly:camera.fly,pos:[...camera.pos],preset:camera.preset},probe:{x:probe.x,z:probe.z,layer:probe.layer,history:probe.history.map(s=>({...s}))}};download(new Blob([JSON.stringify(state)],{type:'application/json'}),'atmos-'+sim.preset+'-seed-'+sim.seed+'.json');toast('Complete atmosphere state saved as JSON.');}
$('saveBtn').onclick=saveState;$('loadBtn').onclick=()=>{$('stateFile').value='';$('stateFile').click();};
function validateApplication(a,n=40,l=12){if(!a)return;if(typeof a!=='object'||!a.camera||!a.render||!a.probe||typeof a.paused!=='boolean')throw Error('Invalid application settings.');let c=a.camera,p=a.probe,r=a.render;if(!Array.isArray(c.target)||c.target.length!==3||!c.target.every(v=>Number.isFinite(v)&&Math.abs(v)<100)||!Array.isArray(c.pos)||c.pos.length!==3||!c.pos.every(v=>Number.isFinite(v)&&Math.abs(v)<200)||![c.azimuth,c.elevation,c.distance,p.x,p.z,p.layer].every(v=>typeof v==='number'&&Number.isFinite(v))||c.distance<5||c.distance>65||Math.abs(c.elevation)>1.5||p.x<0||p.x>1||p.z<0||p.z>1||!Number.isInteger(p.layer)||p.layer<0||p.layer>l-1||!['overview','windward','storm','fly'].includes(c.preset)||typeof c.fly!=='boolean')throw Error('Invalid camera or probe.');const ranges={renderScale:[.35,1],cloudSteps:[24,88],rainDensity:[0,1],exposure:[.5,2],day:[0,24],viz:[0,10],mapLayer:[0,17],probeZ:[-12,12]};for(let [key,[lo,hi]] of Object.entries(ranges))if(typeof r[key]!=='number'||!Number.isFinite(r[key])||r[key]<lo||r[key]>hi)throw Error('Invalid render setting: '+key);for(const key of ['viz','mapLayer','cloudSteps'])if(!Number.isInteger(r[key]))throw Error('Invalid integer render setting: '+key);if(r.mapLayer>=l)throw Error('Invalid map altitude.');if(Object.keys(c).some(key=>!['target','azimuth','elevation','distance','fly','pos','preset'].includes(key)))throw Error('Unrecognized camera setting.');if(Object.keys(r).some(key=>![...Object.keys(ranges),'quality','vectors','contours'].includes(key)))throw Error('Unrecognized render setting.');if(!['low','medium','high'].includes(r.quality)||typeof r.vectors!=='boolean'||typeof r.contours!=='boolean')throw Error('Invalid render quality.');if(!Array.isArray(p.history)||p.history.length>800||p.history.some(v=>!v||typeof v!=='object'||!['seconds','altitude_km','temperature_C','humidity_pct','pressure_hPa','wind_u_ms','wind_v_ms','vertical_ms','vapor_gkg','cloud_gkg','precipitation_mmh','surface_rain_mmh'].every(k=>typeof v[k]==='number'&&Number.isFinite(v[k]))))throw Error('Invalid probe history.');}
$('stateFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw Error('State files must be smaller than 32 MB.');let state=JSON.parse(await file.text());validateApplication(state.application,state.n,state.l);const staged=new Simulation(24,8,0,'fair');staged.load(state);sim=staged;if(state.application){let a=state.application;Object.assign(renderSettings,a.render);Object.assign(camera,a.camera);probe={...a.probe,layer:clamp(a.probe.layer,0,sim.l-1),history:a.probe.history.map(v=>({...v}))};paused=a.paused;}else{probe.history=[];}lastHistory=probe.history.length?probe.history[probe.history.length-1].seconds:-1;renderSettings.probeZ=probe.z*24-12;$('probeLayer').value=probe.layer;$('mapLayer').value=renderSettings.mapLayer;$('visualization').value=renderSettings.viz;$('vectors').checked=renderSettings.vectors;$('contours').checked=renderSettings.contours;syncControls();updateLegend();setPaused(paused);if(renderer)renderer.upload(sim);bolt=null;persist();toast('State loaded. All atmosphere and terrain fields restored.');updateDiagnostics();}catch(err){toast('State rejected: '+err.message);}};
$('csvBtn').onclick=()=>{updateDiagnostics();const columns=['seconds','altitude_km','temperature_C','humidity_pct','pressure_hPa','wind_u_ms','wind_v_ms','vertical_ms','vapor_gkg','cloud_gkg','precipitation_mmh','surface_rain_mmh'];const csv=columns.join(',')+'\n'+probe.history.map(row=>columns.map(k=>Number(row[k]).toFixed(5)).join(',')).join('\n');download(new Blob([csv],{type:'text/csv'}),'atmos-probe-01.csv');toast(probe.history.length+' probe samples exported as CSV.');};
function exportPNG(){const source=view==='3d'?$('world'):$('fieldView');if(view==='3d'&&!renderer){toast('Open the field map to capture this atmosphere.');return;}if(view==='3d')renderer.render(sim,camera,renderSettings,performance.now()/1000,0,bolt);else drawFieldView();const out=document.createElement('canvas');out.width=source.width;out.height=source.height;const ctx=out.getContext('2d');ctx.drawImage(source,0,0);const ratio=out.width/700;ctx.fillStyle='#203c438c';ctx.fillRect(0,0,out.width,48*ratio);ctx.font=18*ratio+'px sans-serif';ctx.fillStyle='#f9f7e7';ctx.fillText('atmos. / '+presets[sim.preset].name,18*ratio,29*ratio);ctx.font=10*ratio+'px monospace';ctx.fillText(modes[renderSettings.viz][0]+' · '+formatTime(sim.time)+' · seed '+sim.seed,out.width*.50,29*ratio);out.toBlob(blob=>{if(blob){download(blob,'atmos-'+sim.preset+'-'+view+'.png');toast('Current '+view+' view exported as PNG.');}else toast('The view could not be captured.');},'image/png');}
$('pngBtn').onclick=exportPNG;$('footerPng').onclick=exportPNG;
let renderError='';try{renderer=new Renderer($('world'));renderer.upload(sim);}catch(e){renderError=e.message;$('errorMessage').textContent=e.message+' The atmosphere model, map, section and editing tools remain available.';$('errorPanel').style.display='flex';console.error(e);}
$('world').addEventListener('webglcontextlost',e=>{e.preventDefault();renderer=null;renderError='The WebGL context was lost.';$('errorMessage').textContent='The graphics context was lost. Use the field map or reload to restore 3D rendering.';$('errorPanel').style.display='flex';});
syncControls();document.querySelectorAll('input[type=range]').forEach(styleRange);updateLegend();updateDiagnostics();
window.addEventListener('resize',()=>{updateDiagnostics();if(view!=='3d')drawFieldView();});
let last=performance.now()/1000,frames=0,fpsStart=last,adaptTime=0,adapted=false;
function frame(nowMs){const now=nowMs/1000,dt=Math.min(.06,Math.max(0,now-last));last=now;updateFly(dt);let changed=false;if(brush.active){applyBrush(Math.min(dt,.04));changed=true;}if(!paused){simAccumulator+=dt;let interval=sim.n>=56?.20:.13;if(simAccumulator>=interval){sim.step(sim.params.timestep);simAccumulator-=interval;changed=true;if(sim.time-lastBolt>25&&sim.charge>.003&&sim.rand()<sim.params.lightning*Math.min(1,sim.charge*20)*.8)strike(false);}}if(renderer){if(changed)renderer.upload(sim);if(view==='3d')renderer.render(sim,camera,renderSettings,now,paused?0:dt,bolt);}if(now-lastDiagnostic>.25){updateDiagnostics();lastDiagnostic=now;}if(view==='3d')updateProbeMarker();frames++;if(now-fpsStart>1){fps=frames/(now-fpsStart);$('fpsStat').textContent=Math.round(fps);frames=0;fpsStart=now;if(fps<23&&view==='3d'&&renderSettings.quality==='medium'&&!adapted)adaptTime++;else adaptTime=Math.max(0,adaptTime-1);if(adaptTime>=4){renderSettings.renderScale=.45;renderSettings.cloudSteps=32;adapted=true;syncControls();$('modelStatus').textContent='Adaptive performance rendering';toast('Rendering adapted for smoother interaction.');}}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
window.atmos={get simulation(){return sim;},get camera(){return camera;},get renderer(){return renderer;},get paused(){return paused;},get probe(){return probe;},get view(){return view;},get tool(){return tool;},get renderSettings(){return{...renderSettings};},diagnostics(){const fields={};for(let [key,arr] of Object.entries(sim.f)){let sum=0,min=Infinity,max=-Infinity,hash=0,finite=true;for(let i=0;i<arr.length;i++){let v=arr[i];sum+=v;min=Math.min(min,v);max=Math.max(max,v);finite=finite&&Number.isFinite(v);hash=(Math.imul(hash,31)+(v*100000|0))|0;}fields[key]={sum,min,max,hash,finite};}return{fields,stats:sim.stats(),probe:readProbe(),paused,view,tool,dimensions:[sim.n,sim.n,sim.l],seed:sim.seed,params:{...sim.params},simulationSeconds:sim.time,simulationSteps:sim.steps,actualDt:sim.lastDt,cfl:sim.lastCFL,fps,renderer:{webgl2:!!renderer,compiled:renderer?.compiled||false,uploads:renderer?.uploads||0,width:$('world').width,height:$('world').height,vertices:renderer?.lineVertices||0,error:renderError},camera:{...camera},lightningCount,autoLightningCount,audio:{enabled:audioEnabled,state:audio?.state||'uninitialized',scheduled:audioTimers.length},interactions:{...interactions},historySamples:probe.history.length,adaptive:adapted};}};
